import { test, expect, devices } from '@playwright/test';

test.describe('Mobile Image Scaling - Responsive Design', () => {
  test.beforeEach(async ({ page }) => {
    // Set mobile viewport
    await page.setViewportSize({ width: 375, height: 667 });
    // Navigate to a page with images
    await page.goto('https://example.com');
  });

  test('should scale images down to fit mobile screen width', async ({ page }) => {
    // Get all images on the page
    const images = page.locator('img');
    const imageCount = await images.count();

    // Verify at least one image exists
    expect(imageCount).toBeGreaterThan(0);

    // Check each image scales properly
    for (let i = 0; i < imageCount; i++) {
      const image = images.nth(i);

      // Wait for image to load
      await image.waitFor({ state: 'visible' });

      // Get the bounding box of the image
      const boundingBox = await image.boundingBox();

      // Verify image width does not exceed viewport width (375px for mobile)
      expect(boundingBox?.width).toBeLessThanOrEqual(375);

      // Verify image is visible
      await expect(image).toBeVisible();
    }
  });

  test('should maintain aspect ratio when scaling images', async ({ page }) => {
    // Get the first image element
    const firstImage = page.locator('img').first();

    // Wait for image to be visible
    await firstImage.waitFor({ state: 'visible' });

    // Get computed styles
    const width = await firstImage.evaluate(el => 
      window.getComputedStyle(el).width
    );
    const height = await firstImage.evaluate(el => 
      window.getComputedStyle(el).height
    );

    // Extract numeric values
    const widthValue = parseFloat(width);
    const heightValue = parseFloat(height);

    // Calculate aspect ratio
    const aspectRatio = widthValue / heightValue;

    // Verify aspect ratio is maintained (should be a valid positive number)
    expect(aspectRatio).toBeGreaterThan(0);
    expect(isFinite(aspectRatio)).toBe(true);

    // Verify width fits within mobile viewport
    expect(widthValue).toBeLessThanOrEqual(375);
  });

